template.script:
// VNPay Token JavaScript functionality
document.addEventListener('DOMContentLoaded', function() {
    // Initialize VNPay Token form
    if (document.getElementById('payment_vnpay_token_form')) {
        initVNPayTokenForm();
    }

    if (document.getElementById('payment_vnpay_token_create_form')) {
        initVNPayTokenCreateForm();
    }
});

function initVNPayTokenForm() {
    // Load saved tokens
    loadSavedTokens();

    // Bind event handlers
    document.getElementById('pay_with_token').addEventListener('click', payWithToken);
    document.getElementById('create_token').addEventListener('click', createToken);
    document.getElementById('delete_token').addEventListener('click', deleteToken);
}

function initVNPayTokenCreateForm() {
    // Bind event handlers
    document.getElementById('create_token_btn').addEventListener('click', createToken);
    document.getElementById('cancel_create_token').addEventListener('click', cancelCreateToken);
}

function loadSavedTokens() {
    // Load saved tokens for the current user
    fetch('/payment/vnpay_token/get-tokens/', {
        method: 'GET',
        headers: {
            'Content-Type': 'application/json',
        }
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            const tokenSelect = document.getElementById('token');
            tokenSelect.innerHTML = 'Select a saved token...';

            data.tokens.forEach(token => {
                const option = document.createElement('option');
                option.value = token.id;
                option.textContent = `${token.card_number} (${token.bank_code})`;
                tokenSelect.appendChild(option);
            });
        }
    })
    .catch(error => {
        console.error('Error loading tokens:', error);
    });
}

function payWithToken() {
    const tokenId = document.getElementById('token').value;
    const amount = document.getElementById('amount').value;
    const currency = document.getElementById('currency').value;

    if (!tokenId || !amount) {
        alert('Please select a token and enter an amount');
        return;
    }

    // Process payment with token
    fetch('/payment/vnpay_token/pay-with-token/', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: new URLSearchParams({
            'token_id': tokenId,
            'amount': amount,
            'currency_id': currency,
        })
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            // Use a safer redirect method to avoid cross-origin issues
            try {
                if (window.top && window.top !== window) {
                    // If we're in an iframe, redirect the top window
                    window.top.location.href = data.payment_url;
                } else {
                    // Normal redirect
                    window.location.href = data.payment_url;
                }
            } catch (error) {
                // Fallback to normal redirect if cross-origin access fails
                console.warn('Cross-origin redirect failed, using fallback:', error);
                window.location.href = data.payment_url;
            }
        } else {
            alert('Payment failed: ' + data.error);
        }
    })
    .catch(error => {
        console.error('Error processing payment:', error);
        alert('Payment failed. Please try again.');
    });
}

function createToken() {
    // Redirect to token creation
    window.location.href = '/payment/vnpay_token/create-token/';
}

function deleteToken() {
    const tokenId = document.getElementById('token').value;

    if (!tokenId) {
        alert('Please select a token to delete');
        return;
    }

    if (!confirm('Are you sure you want to delete this token?')) {
        return;
    }

    // Delete token
    fetch('/payment/vnpay_token/delete-token/', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: new URLSearchParams({
            'token_id': tokenId,
        })
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            alert('Token deleted successfully');
            loadSavedTokens(); // Reload tokens
        } else {
            alert('Failed to delete token: ' + data.error);
        }
    })
    .catch(error => {
        console.error('Error deleting token:', error);
        alert('Failed to delete token. Please try again.');
    });
}

function cancelCreateToken() {
    // Redirect back to payment form
    window.location.href = '/payment/status';
}
